UPDATE borrows
SET status = #{status}, borrow_time = #{borrowTime}, due_time = #{dueTime},
    pickup_admin_id = #{pickupAdminId}, remark = #{remark}
WHERE id = #{id}

UPDATE borrows
SET status = #{status}, return_time = #{returnTime}, confirm_admin_id = #{confirmAdminId}, remark = #{remark}
WHERE id = #{id}

UPDATE borrows
SET status = 5, return_request_time = #{returnRequestTime}, remark = #{remark}
WHERE id = #{id}

UPDATE borrows
SET status = #{status}, return_request_time = NULL, remark = #{remark}
WHERE id = #{id}

UPDATE borrows
SET due_time = #{dueTime}, renew_count = #{renewCount}
WHERE id = #{id}
